A: You can try to use the following code:


const inquirer = require("inquirer");

const options = {
  type: "list",
  message: "What type of headache is it?",
  name: "type",
  choices: ["Nasal", "Otic", "Headache without a specific type", "Other"]
};

const response = inquirer.prompt(options);

switch (response.type) {
  case "Nasal":
    console.log("Nasal headache");
    break;
  case "Otic":
    console.log("Otic headache");
    break;
  case "Headache without a specific type":
    console.log("No type of headache");
    break;
  case "Other":
    console.log("Other headache");
    break;
  default:
    console.log("Please select a headache type");
}


This code will ask you a series of questions based on your type input. If you select "Nasal", it will then prompt you for the type of headache you are experiencing. If you select any other type, it will prompt you for the type of headache you are experiencing.

